import os
import subprocess
import sys

INPUTS = ["report_part1.pdf", "report_part2.pdf"]
OUTPUT = "combined_report.pdf"

# Check inputs exist
for f in INPUTS:
    if not os.path.exists(f):
        sys.exit("Missing input file: " + f)

def page_count(path):
    """Return page count using whichever library is available."""
    try:
        from pypdf import PdfReader
        return len(PdfReader(path).pages)
    except ImportError:
        pass
    try:
        from PyPDF2 import PdfReader
        return len(PdfReader(path).pages)
    except ImportError:
        pass
    try:
        import pypdfium2 as pdfium
        doc = pdfium.PdfDocument(path)
        n = len(doc)
        doc.close()
        return n
    except ImportError:
        pass
    raise RuntimeError("No PDF library available for page counting")

try:
    from pypdf import PdfWriter, PdfReader
except ImportError:
    PdfWriter = PdfReader = None

try:
    from PyPDF2 import PdfWriter as PyPdf2Writer, PdfReader as PyPdf2Reader
except ImportError:
    PyPdf2Writer = PyPdf2Reader = None

merged = False

if PdfWriter is not None:
    writer = PdfWriter()
    for f in INPUTS:
        reader = PdfReader(f)
        for page in reader.pages:
            writer.add_page(page)
    with open(OUTPUT, "wb") as out:
        writer.write(out)
    merged = True
    print("Merged with pypdf")
elif PyPdf2Writer is not None:
    writer = PyPdf2Writer()
    for f in INPUTS:
        reader = PyPdf2Reader(f)
        for page in reader.pages:
            writer.add_page(page)
    with open(OUTPUT, "wb") as out:
        writer.write(out)
    merged = True
    print("Merged with PyPDF2")
else:
    # Try pypdfium2 import_pages
    try:
        import pypdfium2 as pdfium
        out_doc = pdfium.PdfDocument.new()
        for f in INPUTS:
            src = pdfium.PdfDocument(f)
            out_doc.import_pages(src)
            src.close()
        out_doc.save(OUTPUT)
        out_doc.close()
        merged = True
        print("Merged with pypdfium2")
    except ImportError:
        pass

if not merged:
    # Try command-line tools
    for cmd in [
        ["qpdf", "--empty", "--pages", INPUTS[0], INPUTS[1], "--", OUTPUT],
        ["pdftk", INPUTS[0], INPUTS[1], "cat", "output", OUTPUT],
    ]:
        try:
            result = subprocess.run(cmd, capture_output=True, text=True)
            if result.returncode == 0 and os.path.exists(OUTPUT):
                merged = True
                print("Merged with", cmd[0])
                break
        except FileNotFoundError:
            continue

if not merged:
    sys.exit("No usable PDF merge method found (pypdf, PyPDF2, pypdfium2, qpdf, pdftk)")

expected = sum(page_count(f) for f in INPUTS)
actual = page_count(OUTPUT)
print("Expected pages:", expected)
print("Actual pages:", actual)
if actual != expected:
    sys.exit("ERROR: page count mismatch after merge")
print("SUCCESS: combined_report.pdf created with", actual, "pages")

