#!/usr/bin/env python3
"""Raw-level PDF merger for simple, unencrypted PDFs with classic xref tables.

Merges report_part1.pdf + report_part2.pdf -> combined_report.pdf by:
  1. Parsing each document's xref table (following /Prev chains).
  2. Extracting all in-use indirect objects verbatim.
  3. Renumbering objects into a single namespace and rewriting references
     in object dictionaries (stream data left untouched).
  4. Building a combined page tree with a new root /Pages node.
  5. Writing a new xref table and trailer.
"""

import re
import sys

INPUTS = ["report_part1.pdf", "report_part2.pdf"]
OUTPUT = "combined_report.pdf"

REF_RE = re.compile(rb"(\d+)\s+(\d+)\s+R(?![A-Za-z0-9])")
OBJ_HEAD_RE = re.compile(rb"(\d+)\s+(\d+)\s+obj\b")
DICT_RE = re.compile(rb"<<(.*?)>>", re.S)


def parse_trailer_dict(data, pos):
    """Return (dict_bytes, end_pos) for a balanced << >> dictionary."""
    start = data.find(b"<<", pos)
    if start == -1:
        raise ValueError("trailer dict not found")
    depth = 0
    i = start
    while i < len(data):
        if data[i:i + 2] == b"<<":
            depth += 1
            i += 2
        elif data[i:i + 2] == b">>":
            depth -= 1
            i += 2
            if depth == 0:
                return data[start:i], i
        else:
            i += 1
    raise ValueError("unbalanced dict")


def find_startxref(data):
    m = re.search(rb"startxref\s+(\d+)", data)
    if not m:
        raise ValueError("no startxref")
    return int(m.group(1))


def parse_xref_chain(data, xref_pos):
    """Return { (objnum, gen): offset } for in-use entries and the final trailer dict."""
    entries = {}
    trailer = None
    seen = set()
    while True:
        if xref_pos in seen:
            raise ValueError("xref /Prev loop")
        seen.add(xref_pos)
        at = data[xref_pos:xref_pos + 4]
        if at == b"xref":
            m = re.search(rb"xref\s+(.*?)\s+trailer\s*(<<.*?>>)", data[xref_pos:], re.S)
            if not m:
                raise ValueError("cannot parse xref section")
            body, trailer_bytes = m.group(1), m.group(2)
            trailer = trailer_bytes
            # entries: lines "offset gen n" or "offset gen f"
            for line in body.splitlines():
                parts = line.strip().split()
                if len(parts) == 2 and parts[0].isdigit():
                    # subsection header: start count
                    start, count = int(parts[0]), int(parts[1])
                    continue
                if len(parts) == 3 and parts[0].isdigit():
                    off, gen, typ = int(parts[0]), int(parts[1]), parts[2]
                    if typ == b"n":
                        entries[(start, gen)] = off
                        start += 1
                # ignore blank/malformed lines
        else:
            raise ValueError("xref stream (PDF 1.5+) not supported at offset %d" % xref_pos)
        pm = re.search(rb"/Prev\s+(\d+)", trailer)
        if pm:
            xref_pos = int(pm.group(1))
        else:
            break
    return entries, trailer


def parse_object_at(data, offset):
    m = OBJ_HEAD_RE.match(data, offset)
    if not m:
        raise ValueError("no object at offset %d" % offset)
    objnum, gen = int(m.group(1)), int(m.group(2))
    i = offset + m.end()
    e = data.find(b"endobj", i)
    s = data.find(b"stream", i)
    if s != -1 and s < e:
        dict_bytes = data[i:s]
        ss = s + len(b"stream")
        if data[ss:ss + 2] == b"\r\n":
            ss += 2
        elif ss < len(data) and data[ss:ss + 1] in (b"\n", b"\r"):
            ss += 1
        es = data.find(b"endstream", ss)
        if es == -1:
            raise ValueError("missing endstream in object %d" % objnum)
        stream_data = data[ss:es]
        e2 = data.find(b"endobj", es)
        if e2 == -1:
            raise ValueError("missing endobj after stream in object %d" % objnum)
        end = e2 + len(b"endobj")
        return objnum, gen, dict_bytes, stream_data, end
    dict_bytes = data[i:e]
    return objnum, gen, dict_bytes, None, e + len(b"endobj")


def read_all_objects(path):
    with open(path, "rb") as f:
        data = f.read()
    xref_pos = find_startxref(data)
    entries, trailer = parse_xref_chain(data, xref_pos)
    header = data[:8].split(b"\n")[0]
    objects = {}  # (objnum, gen) -> (dict_bytes, stream_data or None)
    for (num, gen), off in entries.items():
        onum, ogen, d, stream, _ = parse_object_at(data, off)
        assert (onum, ogen) == (num, gen), "xref mismatch in %s" % path
        objects[(num, gen)] = (d, stream)
    # catalog from trailer
    cm = re.search(rb"/Root\s+(\d+)\s+(\d+)\s+R", trailer)
    if not cm:
        raise ValueError("no /Root in trailer of %s" % path)
    catalog = (int(cm.group(1)), int(cm.group(2)))
    return header, objects, catalog, trailer


def get_dict_value(dict_bytes, key):
    m = re.search(key + rb"\s+(\d+)\s+(\d+)\s+R", dict_bytes)
    if m:
        return (int(m.group(1)), int(m.group(2)))
    m = re.search(key + rb"\s+\[(.*?)\]", dict_bytes, re.S)
    if m:
        return m.group(1)
    return None


def object_type(dict_bytes):
    m = re.search(rb"/Type\s*/(\w+)", dict_bytes)
    return m.group(1) if m else None


def walk_pages(dict_bytes, objnum, gen, objects, leaves):
    typ = object_type(dict_bytes)
    kids = get_dict_value(dict_bytes, rb"/Kids")
    if typ == b"Pages" and kids is not None:
        for ref in REF_RE.findall(kids):
            walk_pages(*((int(a), int(b)) for a, b in [ref]), objects=objects, leaves=leaves)
    else:
        leaves.append((objnum, gen))


def find_leaf_pages(objects, catalog_pair):
    cat_dict = objects[catalog_pair][0]
    pages_ref = get_dict_value(cat_dict, rb"/Pages")
    if pages_ref is None:
        raise ValueError("catalog has no /Pages")
    leaves = []
    walk_pages(objects[pages_ref][0], pages_ref[0], pages_ref[1], objects, leaves)
    return leaves


def rewrite_refs(text, mapping):
    def sub(m):
        key = (int(m.group(1)), int(m.group(2)))
        new = mapping.get(key)
        if new is None:
            return m.group(0)
        return b"%d 0 R" % new
    return REF_RE.sub(sub, text)


def main():
    docs = []
    for path in INPUTS:
        header, objects, catalog, trailer = read_all_objects(path)
        leaves = find_leaf_pages(objects, catalog)
        docs.append({"header": header, "objects": objects, "catalog": catalog,
                     "trailer": trailer, "leaves": leaves})
        print("%s: %d in-use objects, %d leaf pages, header %r"
              % (path, len(objects), len(leaves), header))

    # Build single numbering: doc1 objects, then doc2 objects.
    mapping = {}
    ordered = []  # (doc_index, orig_pair, dict_bytes, stream)
    next_num = 1
    for di, doc in enumerate(docs):
        for pair in sorted(doc["objects"].keys()):
            mapping[(di, pair)] = next_num
            next_num += 1
    new_root_num = next_num
    next_num += 1

    # Sanity: no collisions between doc1 and doc2 original numbers after mapping.
    doc1_pairs = {p for p in docs[0]["objects"]}
    doc2_pairs = {p for p in docs[1]["objects"]}
    overlap = doc1_pairs & doc2_pairs
    if overlap:
        print("note: overlapping object numbers across docs:", overlap)

    # Catalog to reuse: doc1's catalog.
    cat_di, cat_pair = 0, docs[0]["catalog"]
    cat_new = mapping[(0, cat_pair)]

    # Rewrite each object's dictionary, overriding /Parent on leaf pages
    # and /Pages in the reused catalog.
    out_objects = []
    for di, doc in enumerate(docs):
        for pair in sorted(doc["objects"].keys()):
            d, stream = doc["objects"][pair]
            new_num = mapping[(di, pair)]
            rewritten = rewrite_refs(d, {p: mapping[(di, p)] for p in doc["objects"]})
            if pair in doc["leaves"]:
                rewritten = re.sub(rb"/Parent\s+\d+\s+\d+\s+R",
                                   b"/Parent %d 0 R" % new_root_num, rewritten)
            out_objects.append((new_num, rewritten, stream))

    # New root pages object.
    kids_refs = b" ".join(b"%d 0 R" % mapping[(di, pair)]
                          for di, doc in enumerate(docs) for pair in sorted(doc["leaves"]))
    root_pages = (b"/Type /Pages /Kids [ " + kids_refs + b" ] /Count %d" %
                  (len(docs[0]["leaves"]) + len(docs[1]["leaves"])))
    out_objects.append((new_root_num, root_pages, None))

    # Reused catalog (doc1's), with /Pages pointed at new root; drop /AcroForm.
    cat_d, cat_stream = docs[0]["objects"][cat_pair]
    cat_rewritten = rewrite_refs(cat_d, {p: mapping[(0, p)] for p in docs[0]["objects"]})
    cat_rewritten = re.sub(rb"/Pages\s+\d+\s+\d+\s+R", b"/Pages %d 0 R" % new_root_num,
                           cat_rewritten)
    if re.search(rb"/AcroForm", cat_rewritten):
        print("note: dropping /AcroForm from reused catalog (forms not merged)")
        cat_rewritten = re.sub(rb"\s*/AcroForm\s+\d+\s+\d+\s+R", b"", cat_rewritten)
    # Ensure catalog still has /Pages (replaced) - replace catalog in list.
    for i, (num, _, _) in enumerate(out_objects):
        if num == cat_new:
            out_objects[i] = (num, cat_rewritten, cat_stream)
            break

    # Version header: use the higher of the two documents.
    version = max(docs[0]["header"], docs[1]["header"])

    # Build output.
    chunks = [version + b"\n%\xe2\xe3\xcf\xd3\n"]
    offsets = {}
    for num, d, stream in sorted(out_objects):
        offsets[num] = len(b"".join(chunks))  # bytes written so far
        obj = b"%d 0 obj\n" % num + d
        if stream is not None:
            obj += b"\nstream\n" + stream + b"\nendstream"
        obj += b"\nendobj\n"
        chunks.append(obj)

    size = new_root_num + 1
    xref_pos = len(b"".join(chunks))
    xref = b"xref\n0 %d\n" % size
    xref += b"0000000000 65535 f \n"
    for num in range(1, size):
        off = offsets.get(num)
        if off is None:
            raise ValueError("missing offset for object %d" % num)
        xref += b"%010d 00000 n \n" % off

    trailer = b"trailer\n<< /Size %d /Root %d 0 R " % (size, cat_new)
    info_m = re.search(rb"/Info\s+(\d+)\s+(\d+)\s+R", docs[0]["trailer"])
    if info_m:
        info_pair = (int(info_m.group(1)), int(info_m.group(2)))
        if info_pair in docs[0]["objects"]:
            trailer += b"/Info %d 0 R " % mapping[(0, info_pair)]
    trailer += b">>\nstartxref\n%d\n%%%%EOF\n" % xref_pos

    with open(OUTPUT, "wb") as f:
        f.write(b"".join(chunks))
        f.write(xref)
        f.write(trailer)

    print("Wrote", OUTPUT, "with", len(out_objects), "objects,", size, "xref entries")
    print("New root pages object:", new_root_num, "catalog:", cat_new)


if __name__ == "__main__":
    main()
